"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9547],{75032:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PlacementCameraController","desc":"Owns the camera while build mode is active: a straight-down (90\xb0) view\\nwith its yaw locked at entry. The player is frozen (their\\nHumanoidRootPart is anchored locally) and move input \u2014 WASD, gamepad\\nstick, mobile thumbstick \u2014 pans the camera instead, plus scroll-wheel\\nzoom and PC edge scroll. The focus stays within PlacementConfig.PanRadius\\nof the player so the camera (the placement ray origin) stays inside\\nPlacementServer\'s 55-stud origin limit.\\n\\nEntry swings the camera over the player to straight down at its\\nthird-person distance, then zooms out to the top-down height. Exit plays the\\nCoolTransitions Checkerboard; the top-down\\nview is held until the screen is covered, then the camera is handed back\\nto CameraController (which resumes its pre-build yaw/pitch).\\nDeath/reset tears down instantly with no transition.\\n\\nOn PC the cursor is freed (Signals.RequestMouseIcon) while build mode is\\nactive, because the placement raycast aims from the cursor position.","realm":["Client"],"source":{"line":26,"path":"src/StarterPlayer/StarterPlayerScripts/PlacementCameraController.client.luau"}}')}}]);